// 5 dígitos y nada más. Si no, ni se molesta en llamar a Envia.
const cp = String(($json.body || {}).codigo_postal || '').trim();
if (!/^\d{5}$/.test(cp)) {
  return [{ json: { valido: false, motivo: 'cp_invalido', codigo_postal: cp } }];
}
return [{ json: { valido: true, codigo_postal: cp } }];

// Filtra por ciudad y estado; si hay coordenadas, ordena por distancia real.
// Devuelve 3 como máximo, porque el cliente elige de una lista corta.
const zip = $('Envia · validate-zip-code').first().json;
const datos = zip.data || zip;
const ciudad = (datos.city || datos.locality || '').toString().toLowerCase();
const estado = (datos.state || '').toString().toLowerCase();
const lat = Number(datos.latitude ?? datos.lat);
const lon = Number(datos.longitude ?? datos.lng);
const cp = $('¿5 dígitos?').first().json.codigo_postal;

const crudas = $input.first().json;
const sucursales = crudas.data || crudas.branches || [];

const norm = s => (s || '').toString().toLowerCase().trim();
const km = (a1, o1, a2, o2) => {
  const R = 6371, r = Math.PI / 180;
  const d1 = (a2 - a1) * r, d2 = (o2 - o1) * r;
  const x = Math.sin(d1/2)**2 + Math.cos(a1*r) * Math.cos(a2*r) * Math.sin(d2/2)**2;
  return 2 * R * Math.asin(Math.sqrt(x));
};

let candidatas = sucursales.filter(s => norm(s.city) === ciudad && (!estado || norm(s.state) === estado));
if (!candidatas.length) candidatas = sucursales.filter(s => norm(s.state) === estado);

const hayCoords = Number.isFinite(lat) && Number.isFinite(lon)
  && candidatas.some(s => Number.isFinite(Number(s.latitude ?? s.lat)));

if (hayCoords) {
  candidatas = candidatas
    .map(s => ({ s, d: km(lat, lon, Number(s.latitude ?? s.lat), Number(s.longitude ?? s.lng)) }))
    .filter(x => Number.isFinite(x.d))
    .sort((a, b) => a.d - b.d)
    .map(x => ({ ...x.s, distancia_km: Math.round(x.d * 10) / 10 }));
}

const tres = candidatas.slice(0, 3).map(s => ({
  nombre: s.name || s.branch_name,
  direccion: [s.street, s.number, s.district, s.city, s.state].filter(Boolean).join(', '),
  codigo_postal: s.postal_code,
  distancia_km: s.distancia_km ?? null,
  mapa: (s.latitude && s.longitude)
    ? `https://www.google.com/maps/search/?api=1&query=${s.latitude},${s.longitude}`
    : `https://www.google.com/maps/search/?api=1&query=${encodeURIComponent((s.name || '') + ' ' + (s.city || ''))}`
}));

return [{ json: tres.length
  ? { ok: true, codigo_postal: cp, ciudad: datos.city, estado: datos.state, ordenadas_por: hayCoords ? 'distancia' : 'ciudad', sucursales: tres }
  : { ok: false, motivo: 'sin_cobertura', codigo_postal: cp, ciudad: datos.city, estado: datos.state } }];
